use crate::net::minecraft::item::crafting::Ingredient::Ingredient;
use crate::net::minecraft::item::ItemStack::ItemStack;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum RecipeKind {
    Dynamic,
    Shaped,
    Shapeless,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum RecipeCategory {
    Search,
    Tools,
    BuildingBlocks,
    Misc,
    Redstone,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct StackSpec {
    pub itemId: i16,
    pub metadata: i16,
    pub count: u8,
}
impl StackSpec {
    pub const EMPTY: Self = Self {
        itemId: -1,
        metadata: 0,
        count: 0,
    };
    pub fn toItemStack(self) -> ItemStack {
        if self.itemId < 0 || self.count == 0 {
            ItemStack::EMPTY
        } else {
            ItemStack {
                itemId: self.itemId,
                count: self.count,
                itemDamage: self.metadata,
                tagCompound: None,
            }
        }
    }
}

/// One entry from the exact protocol registry order produced by the official
/// Minecraft 1.12.2 JAR. MCP registers eleven dynamic recipes explicitly, then
/// Java ZIP-FS walks `/assets/minecraft/recipes` in reverse lexicographic path
/// order. Walking an extracted directory is filesystem-dependent and produces
/// incorrect `CPacketPlaceRecipe` numeric IDs.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct RecipeDefinition {
    pub id: i32,
    pub registryName: &'static str,
    pub className: &'static str,
    pub group: &'static str,
    pub kind: RecipeKind,
    pub width: u8,
    pub height: u8,
    pub output: StackSpec,
    pub category: RecipeCategory,
    /// Semicolon-separated slots; alternatives within one slot use `|`.
    /// Each stack is `itemId:metadata:count`. Empty shaped slots are empty fields.
    pub ingredients: &'static str,
}
impl RecipeDefinition {
    pub const fn isDynamic(&self) -> bool {
        matches!(self.kind, RecipeKind::Dynamic)
    }
    pub const fn fits(&self, width: usize, height: usize) -> bool {
        match self.kind {
            RecipeKind::Shaped => width >= self.width as usize && height >= self.height as usize,
            RecipeKind::Shapeless => width.saturating_mul(height) >= self.ingredientSlotCount(),
            RecipeKind::Dynamic => false,
        }
    }
    pub const fn ingredientSlotCount(&self) -> usize {
        if self.ingredients.is_empty() {
            0
        } else {
            let bytes = self.ingredients.as_bytes();
            let mut count = 1usize;
            let mut i = 0usize;
            while i < bytes.len() {
                if bytes[i] == b';' {
                    count += 1;
                }
                i += 1;
            }
            count
        }
    }
    pub fn outputStack(&self) -> ItemStack {
        self.output.toItemStack()
    }
    pub fn ingredientList(&self) -> Vec<Ingredient> {
        if self.ingredients.is_empty() {
            return Vec::new();
        }
        self.ingredients
            .split(';')
            .map(Ingredient::fromEncodedAlternatives)
            .collect()
    }
}

