pub fn getRecipeById(id: i32) -> Option<&'static RecipeDefinition> {
    usize::try_from(id)
        .ok()
        .and_then(|index| RECIPES.get(index))
        .filter(|recipe| recipe.id == id)
}

pub fn getRecipeByName(name: &str) -> Option<&'static RecipeDefinition> {
    RECIPES.iter().find(|recipe| recipe.registryName == name)
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn registry_matches_mcp_bootstrap_order() {
        assert_eq!(RECIPES.len(), 443);
        assert_eq!(RECIPES[0].registryName, "minecraft:armordye");
        assert_eq!(RECIPES[10].registryName, "minecraft:shulkerboxcoloring");
        assert_eq!(RECIPES[11].registryName, "minecraft:yellow_wool");
        assert_eq!(RECIPES[26].registryName, "minecraft:wooden_pickaxe");
        assert_eq!(RECIPES[28].registryName, "minecraft:wooden_door");
        assert_eq!(RECIPES[42].registryName, "minecraft:torch");
        assert_eq!(RECIPES[427].registryName, "minecraft:birch_door");
        assert_eq!(RECIPES[442].registryName, "minecraft:acacia_boat");
        assert!(RECIPES[..11].iter().all(RecipeDefinition::isDynamic));
        assert!(RECIPES[11..].iter().all(|recipe| !recipe.isDynamic()));
    }
}
